}

pub fn FreeIfGuard(comptime T: type) type {
    return struct {
        allocator: std.mem.Allocator,
        slice: T,
        active: bool,
        __cp_dropped: bool = false,

pub fn __cp_deinit(self: *@This()) void {
            if (self.__cp_dropped) return;
            self.__cp_dropped = true;
