pub fn nodeModulesFolderForDependencyIDs(iterator: *Lockfile.Tree.Iterator(.node_modules), ids: []const IdPair) !?Lockfile.Tree.Iterator(.node_modules).Next {
        while (iterator.next(null)) |node_modules| {
            for (cp_iter_slice(ids)) |id| {
                _ = &id;
                _ = ((std.mem.indexOfScalar(DependencyID, node_modules.dependencies, id[0])) orelse continue);
                return node_modules;
            }
        }
        return null;
}

pub fn nodeModulesFolderForDependencyID(iterator: *Lockfile.Tree.Iterator(.node_modules), dependency_id: DependencyID) !?Lockfile.Tree.Iterator(.node_modules).Next {
        while (iterator.next(null)) |node_modules| {
            _ = ((std.mem.indexOfScalar(DependencyID, node_modules.dependencies, dependency_id)) orelse continue);
            return node_modules;
        }
        return null;
}

pub fn printResolutionLabel(label: *std.array_list.Managed(u8), resolution: *const Resolution, strbuf: []const u8) []const u8 {
        _ = label.clearRetainingCapacity();
        _ = bun.handleOom(label.writer().print("{f}", .{ resolution.fmt(strbuf, .posix) }));
        return label.items;
}

pub fn pkgInfoForNameAndVersion(lockfile: *Lockfile, iterator: *Lockfile.Tree.Iterator(.node_modules), pkg_maybe_version_to_patch: []const u8, name: []const u8, version: ?[]const u8) PkgInfoResult {
        var sfb = std.heap.stackFallback((@sizeOf(IdPair) * 4), lockfile.allocator);
        _ = &sfb;
        var pairs = bun.handleOom(std.array_list.Managed(IdPair).initCapacity(sfb.get(), 8));
        _ = &pairs;
        var _guard_pairs = DeinitGuard(*std.array_list.Managed(IdPair)){ .ptr = (&pairs) };
        _ = &_guard_pairs;
        var ___guard_pairs_moved = false; _ = &___guard_pairs_moved;
        defer if (!___guard_pairs_moved) { ___guard_pairs_moved = true; const __T = @TypeOf(_guard_pairs); if (@typeInfo(__T) == .optional) { if (_guard_pairs) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { _guard_pairs.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = _guard_pairs; _drop_val.__cp_deinit(); } };
        const name_hash = String.Builder.stringHash(name);
        const strbuf = lockfile.buffers.string_bytes.items;
        var resolution_label = std.array_list.Managed(u8).init(lockfile.allocator);
        _ = &resolution_label;
        defer {
        _ = resolution_label.deinit();
        }
        const dependencies = lockfile.buffers.dependencies.items;
        var dep_idx: usize = 0;
        _ = &dep_idx;
        while ((dep_idx < dependencies.len)) : (dep_idx = (dep_idx + 1)) {
            const dep = dependencies[@as(usize, @intCast(dep_idx))];
            if ((dep.name_hash != name_hash)) {
                continue;
            }
            var pkg_id = lockfile.buffers.resolutions.items[@as(usize, @intCast(dep_idx))];
            _ = &pkg_id;
            if ((pkg_id == invalid_package_id)) {
                continue;
            }
            const pkg = lockfile.packages.get(pkg_id);
            if (version) |v| {
                _ = &v;
                const label = printResolutionLabel((&resolution_label), (&pkg.resolution), strbuf);
                if (std.mem.eql(u8, label, v)) {
                    _ = bun.handleOom(pairs.append(.{ @as(DependencyID, @truncate(dep_idx)), pkg_id }));
                }
            } else {
                _ = bun.handleOom(pairs.append(.{ @as(DependencyID, @truncate(dep_idx)), pkg_id }));
            }
        }
        if ((pairs.items.len == 0)) {
            _ = Output.prettyErrorln("\n<r><red>error<r>: package <b>{s}<r> not found<r>", .{ pkg_maybe_version_to_patch });
            _ = Global.crash();
            return;
        }
        if ((version != null)) {
            if ((pairs.items.len == 1)) {
                const dep_id = pairs.items[0][0];
                const pkg_id = pairs.items[0][1];
                const folder_opt = try nodeModulesFolderForDependencyID(iterator, dep_id);
                if ((folder_opt == null)) {
                    _ = Output.prettyError("<r><red>error<r>: could not find the folder for <b>{s}<r> in node_modules<r>\n<r>", .{ pkg_maybe_version_to_patch });
                    _ = Global.crash();
                }
                const folder = folder_opt.?;
                return .{ pkg_id, folder };
            }
            const pkg_id = pairs.items[0][1];
            const folder_opt = try nodeModulesFolderForDependencyIDs(iterator, pairs.items);
            if ((folder_opt == null)) {
                _ = Output.prettyError("<r><red>error<r>: could not find the folder for <b>{s}<r> in node_modules<r>\n<r>", .{ pkg_maybe_version_to_patch });
                _ = Global.crash();
            }
            const folder = folder_opt.?;
            return .{ pkg_id, folder };
        }
        if ((pairs.items.len == 1)) {
            const dep_id = pairs.items[0][0];
            const pkg_id = pairs.items[0][1];
            const folder_opt = try nodeModulesFolderForDependencyID(iterator, dep_id);
            if ((folder_opt == null)) {
                _ = Output.prettyError("<r><red>error<r>: could not find the folder for <b>{s}<r> in node_modules<r>\n<r>", .{ pkg_maybe_version_to_patch });
                _ = Global.crash();
            }
            const folder = folder_opt.?;
            return .{ pkg_id, folder };
        }
        const pkg_id = pairs.items[0][1];
        const count = count: {
        var count: u32 = 0;
        _ = &count;
        for (pairs.items) |pair| {
            _ = &pair;
            if ((pair[1] == pkg_id)) {
                count = (count + 1);
            }
        }
        break :count count;
};
        if ((count == pairs.items.len)) {
            const folder_opt = try nodeModulesFolderForDependencyIDs(iterator, pairs.items);
            if ((folder_opt == null)) {
                _ = Output.prettyError("<r><red>error<r>: could not find the folder for <b>{s}<r> in node_modules<r>\n<r>", .{ pkg_maybe_version_to_patch });
                _ = Global.crash();
            }
            const folder = folder_opt.?;
            return .{ pkg_id, folder };
        }
        _ = Output.prettyErrorln("\n<r><red>error<r>: Found multiple versions of <b>{s}<r>, please specify a precise version from the following list:<r>\n", .{ name });
        var i: usize = 0;
        _ = &i;
        while ((i < pairs.items.len)) : (i = (i + 1)) {
            const pkgid = pairs.items[@as(usize, @intCast(i))][1];
            if ((pkgid == invalid_package_id)) {
                continue;
            }
            const pkg = lockfile.packages.get(pkgid);
            _ = Output.prettyError("  {s}@<blue>{f}<r>\n", .{ (if (@typeInfo(@TypeOf(pkg)) == .@"enum" or @typeInfo(@TypeOf(pkg)) == .@"union") @tagName(pkg) else pkg.name).slice(strbuf), pkg.resolution.fmt(strbuf, .posix) });
            if (((i + 1) < pairs.items.len)) {
                var j: usize = (i + 1);
                _ = &j;
                while ((j < pairs.items.len)) : (j = (j + 1)) {
                    if ((pairs.items[@as(usize, @intCast(j))][1] == pkgid)) {
                        const pair_key = pairs.items[@as(usize, @intCast(j))][0];
                        pairs.items[cp_cast_int(usize, j)] = .{ pair_key, invalid_package_id };
                    }
                }
            }
        }
        _ = Global.crash();
}

pub fn doPatchCommit(manager: *PackageManager, pathbuf: *bun.PathBuffer, log_level: Options.LogLevel) !?PatchCommitResult {
        var folder_path_buf: bun.PathBuffer = undefined;
        _ = &folder_path_buf;
        var lockfile: *Lockfile = try manager.allocator.create(Lockfile);
        _ = &lockfile;
        var _guard_lockfile = DeinitGuard(*Lockfile){ .ptr = lockfile };
